using MediatR;

namespace Normora.Modules.Conversations.Application.SavedAnswers.Commands;

/// <summary>
/// Command to bookmark an AI assistant message for the authenticated employee.
/// Handled by <see cref="SaveAnswerCommandHandler"/>.
/// </summary>
/// <remarks>
/// Invariants & Security:
/// - Verifies that the target message was generated by the AI Assistant (MessageRole.Assistant).
/// - Enforces that the conversation belongs to the caller within the ambient TenantId (BOLA protection).
/// - Idempotent: returns existing SavedAnswer ID if already bookmarked.
/// </remarks>
/// <param name="MessageId">The unique identifier of the assistant message turn to bookmark.</param>
public record SaveAnswerCommand(Guid MessageId) : IRequest<Guid>;

